import{_ as o,c as r,o as a,ag as i}from"./chunks/framework.ymCRTBvy.js";const _=JSON.parse('{"title":"14.1 获取沙盒目录路径（Documents_Library）","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_networking_persistence/14.1_获取沙盒目录路径（Documents_Library）.md","filePath":"swift/uikit/uikit_networking_persistence/14.1_获取沙盒目录路径（Documents_Library）.md"}'),t={name:"swift/uikit/uikit_networking_persistence/14.1_获取沙盒目录路径（Documents_Library）.md"};function n(c,e,l,s,d,u){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="_14-1-获取沙盒目录路径-documents-library" tabindex="-1">14.1 获取沙盒目录路径（Documents_Library） <a class="header-anchor" href="#_14-1-获取沙盒目录路径-documents-library" aria-label="Permalink to &quot;14.1 获取沙盒目录路径（Documents_Library）&quot;">​</a></h1><h2 id="探索沙盒-应用数据存储的宝藏地-🗺️" tabindex="-1">探索沙盒：应用数据存储的宝藏地 🗺️ <a class="header-anchor" href="#探索沙盒-应用数据存储的宝藏地-🗺️" aria-label="Permalink to &quot;探索沙盒：应用数据存储的宝藏地 🗺️&quot;">​</a></h2><p>在iOS开发中，每个应用都有一个独立的“沙盒”环境，这是一个安全且隔离的文件系统区域。你不能随意访问其他应用的数据，这极大地增强了系统的安全性。理解沙盒目录结构是进行文件存储的关键第一步！</p><h2 id="documents-目录-用户数据的理想家园-🏡" tabindex="-1">Documents 目录：用户数据的理想家园 🏡 <a class="header-anchor" href="#documents-目录-用户数据的理想家园-🏡" aria-label="Permalink to &quot;Documents 目录：用户数据的理想家园 🏡&quot;">​</a></h2><p><code>Documents</code> 目录是存储用户生成数据和应用特定文件的最佳位置。例如，如果你正在开发一个笔记应用，用户的笔记内容就应该保存在这里。这些数据会通过iCloud进行备份，确保用户数据永不丢失。</p><ul><li><strong>获取路径</strong>：你可以使用 <code>FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)</code> 来获取 <code>Documents</code> 目录的URL。</li><li><strong>备份特性</strong>：存储在此目录下的文件会自动被iCloud和iTunes备份，这对于用户数据的持久化至关重要。</li><li><strong>常见用途</strong>： <ol><li>用户创建的文档和媒体文件。</li><li>应用需要长期保存的配置数据。</li><li>下载的离线内容。</li></ol></li></ul><h2 id="library-目录-系统和缓存数据的归属-📚" tabindex="-1">Library 目录：系统和缓存数据的归属 📚 <a class="header-anchor" href="#library-目录-系统和缓存数据的归属-📚" aria-label="Permalink to &quot;Library 目录：系统和缓存数据的归属 📚&quot;">​</a></h2><p><code>Library</code> 目录主要用于存储应用支持文件和缓存数据。这个目录又细分为几个子目录，其中最常用的是 <code>Caches</code> 和 <code>Application Support</code>。这些文件通常不直接暴露给用户，但对应用的正常运行至关重要。</p><h3 id="caches-目录-临时数据的理想场所-⚡" tabindex="-1">Caches 目录：临时数据的理想场所 ⚡ <a class="header-anchor" href="#caches-目录-临时数据的理想场所-⚡" aria-label="Permalink to &quot;Caches 目录：临时数据的理想场所 ⚡&quot;">​</a></h3><p><code>Caches</code> 目录用于存放应用运行时产生的临时文件，这些文件在应用关闭后可以被系统删除，以释放存储空间。例如，网络请求的图片缓存就非常适合放在这里。</p><ul><li><strong>获取路径</strong>：使用 <code>FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)</code> 获取。</li><li><strong>不被备份</strong>：<code>Caches</code> 目录下的数据不会被iCloud或iTunes备份，因此不应存放重要数据。</li><li><strong>系统清理</strong>：当设备存储空间不足时，系统可能会自动清理此目录下的文件。</li></ul><h3 id="application-support-目录-非用户数据的好选择-⚙️" tabindex="-1">Application Support 目录：非用户数据的好选择 ⚙️ <a class="header-anchor" href="#application-support-目录-非用户数据的好选择-⚙️" aria-label="Permalink to &quot;Application Support 目录：非用户数据的好选择 ⚙️&quot;">​</a></h3><p><code>Application Support</code> 目录用于存储应用运行所需的非用户数据，例如数据库文件、自定义字体或应用内部的配置。这些数据通常需要长期保存，但又不需要用户直接访问。</p><ul><li><strong>获取路径</strong>：通过 <code>FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)</code> 获取。</li><li><strong>会被备份</strong>：此目录下的数据会被备份，因此适合存放重要的应用支持文件。</li><li><strong>数据隔离</strong>：它提供了一个结构化的方式来组织应用内部的各种支持文件。</li></ul><h2 id="temp-目录-真正的临时文件区-💨" tabindex="-1">Temp 目录：真正的临时文件区 💨 <a class="header-anchor" href="#temp-目录-真正的临时文件区-💨" aria-label="Permalink to &quot;Temp 目录：真正的临时文件区 💨&quot;">​</a></h2><p><code>Temp</code> 目录顾名思义，是存放真正临时文件的区域。这些文件在应用不再需要时应该立即删除，并且系统会定期清理此目录。例如，在处理大型文件时，你可以先将其下载到 <code>Temp</code> 目录，处理完毕后立即删除。</p><ul><li><strong>获取路径</strong>：你可以直接使用 <code>NSTemporaryDirectory()</code> 函数来获取 <code>Temp</code> 目录的路径。</li><li><strong>生命周期短</strong>：此目录下的文件生命周期非常短，不保证持久性。</li><li><strong>不被备份</strong>：<code>Temp</code> 目录下的数据绝不会被备份。</li></ul><p>理解这些沙盒目录的用途和特性，能让你更高效、更安全地管理应用数据。选择正确的目录来存储不同类型的数据，是构建健壮iOS应用的关键一步！🚀</p>',18)]))}const h=o(t,[["render",n]]);export{_ as __pageData,h as default};
